package com.nuvio.tv.data.trailer

data class TrailerPlaybackSource(
    val videoUrl: String,
    val audioUrl: String? = null
)

data class TrailerSubtitleTrack(
    val languageCode: String,
    val url: String,
    val isAutoGenerated: Boolean
)

/**
 * Preferred language first, author captions before auto-generated. Falls back to the only
 * language available so trailers published in a single other language still get subtitles.
 */
internal fun pickTrailerSubtitle(
    tracks: List<TrailerSubtitleTrack>,
    preferredLanguage: String
): TrailerSubtitleTrack? {
    fun baseLanguage(code: String) = code.substringBefore('-').lowercase()
    val preferred = baseLanguage(preferredLanguage)
    val candidates = tracks.filter { baseLanguage(it.languageCode) == preferred }.ifEmpty {
        tracks.takeIf { all -> all.distinctBy { baseLanguage(it.languageCode) }.size == 1 }.orEmpty()
    }
    return candidates.minByOrNull { if (it.isAutoGenerated) 1 else 0 }
}

private val CAPTION_FORMAT_PARAM = Regex("(?<=[?&])fmt=[^&]*")

/**
 * YouTube serves XML timedtext by default and some clients pin `fmt=srv3` in the URL;
 * vtt is the only format Media3 parses out of the box.
 */
internal fun captionUrlAsVtt(baseUrl: String): String =
    if (CAPTION_FORMAT_PARAM.containsMatchIn(baseUrl)) {
        CAPTION_FORMAT_PARAM.replace(baseUrl, "fmt=vtt")
    } else {
        "$baseUrl&fmt=vtt"
    }
